 if(type==='buildings'){items=uniq(D.buildings.filter(b=>!isSuppressed('buildings',b.gameobject_id)));title='Buildings';sub='Construction material inputs, worker limits, housing capacity and production.';tabs=[['all','All'],['production','Production'],['homes','Housing'],['fields','Fields & plants'],['other','Other']];if(filter!=='all')items=items.filter(b=>category(b)===filter)}
 if(type==='resources'||type==='food'){items=uniq(D.resources.filter(r=>type==='food'?r.publicly_named&&r.need_units.FoodUnits>0:showInternal||r.publicly_named),r=>r.publicly_named?r.name:r.id);title=type==='food'?'Food':'Resources';sub=type==='food'?'Food values, producers and recipe inputs.':'Resource values, producers, consumers and construction uses.';if(type==='resources')tabs=[['all','Named resources'],['internal','Include intermediates']]}
 if(type==='chains'){items=uniq(D.buildings.filter(b=>b.formula_ids.length&&!isSuppressed('chains',b.gameobject_id)));title='Production chains';sub='Inputs, outputs and intermediate steps. Ratios are derived from stored formulas; throughput is unverified.';tabs=[['all','All'],['complete','Complete balances'],['complex','Unresolved balances']];if(filter==='complete')items=items.filter(b=>b.derived_recipes.some(r=>!r.caveats.length));if(filter==='complex')items=items.filter(b=>!b.derived_recipes.some(r=>!r.caveats.length))}
