 if(direct)return direct;
 if(type==='levels'){const parent=V.entries.find(e=>e.associated_level_ids?.includes(o.id));if(parent)return {availability_status:'public_release_unconfirmed',note:'Associated with '+parent.name+' and packaged update '+parent.packaged_update_association+'. Public release is unconfirmed.',parent_evidence:parent}}
 if(type==='heroes'){const release=V.public_release_history.find(e=>e.id===o.name);if(release)return {...release,availability_status:'official_release_notes_evidence'}}
