function scenarioObjective(o){
 const kinds={Have:'Have',Create:'Produce / make',Consume:'Consume / recycle',VillagerCount:'Population',Happiness:'Happiness',Extract:'Extract',Concern:'Need satisfaction',Housing:'Settled',HaveInBuilding:'Have in building',ReachDay:'Reach day',GearedPercentage:'Equipped villagers',UseSocialSpot:'Use social spot'},comparison={Equal:'=',NotEqual:'≠',Less:'<',LessOrEqual:'≤',Greater:'>',GreaterOrEqual:'≥'};
 const relevant=['Have','Create','Consume','Extract','HaveInBuilding','GearedPercentage','UseSocialSpot'].includes(o.condition_name);
 let target=relevant?scenarioAsset(o.target):o.condition_name==='Concern'?esc(o.concern_name):'—';
 if(o.condition_name==='HaveInBuilding')target+=' in '+scenarioAsset(o.building);
 const percent=['Concern','Housing','Happiness','GearedPercentage'].includes(o.condition_name);
 const resource=o.target?.localization_key?.startsWith('Resource.');
 const meanings={Have:resource?'Have this amount in stock; making it earlier is not enough.':'Have this many of the target present.',Create:'Produce this amount over the scenario; this is a production total, not a stock target.',HaveInBuilding:'Have this amount in the specified building.',Housing:o.NeededAmount===100?'Have everyone settled.':'Have this percentage of villagers settled.',Concern:o.concern_name==='Housing'?'Satisfy Housing. This is a need-satisfaction objective, separate from “Have everyone settled”.':'Reach this level of satisfaction for the named need.',Happiness:'Reach this happiness percentage.',VillagerCount:'Reach this population.',GearedPercentage:'Equip this percentage of villagers with the target item.',ReachDay:'Reach the specified day.',Extract:'Extract this amount from the source.',Consume:'Consume the resource or recycle/remove the target; the action depends on the target.',UseSocialSpot:'Use the named social spot the required number of times.'};
 return `<tr><td>${esc(kinds[o.condition_name]||o.condition_name)}</td><td>${target}</td><td>${esc(comparison[o.comparison_name]||o.comparison_name)} ${esc(o.NeededAmount)}${percent?'%':''}</td><td>${esc(meanings[o.condition_name]||'See the objective source for details.')}</td></tr>`;
}
function objectiveResource(o){const key=o.target?.localization_key;if(!key||!key.startsWith('Resource.'))return null;return D.resources.find(r=>r.localization_key===key&&r.publicly_named)||null}
function recipeForLevel(r,level){const entries=D.resources.filter(x=>x.name===r.name).flatMap(x=>x.made_from||[]);if(!entries.length)return null;const buildable=new Set((level.scenario?.buildable_entries||[]).map(x=>x.gameobject_id)),isTrade=m=>/trading/i.test(m.building_name);return entries.find(m=>buildable.has(m.building_id)&&!isTrade(m))||entries.find(m=>!isTrade(m))||null}
function expandNeeds(level,wanted){const totals=new Map(),add=(r,count,direct,via)=>{const t=totals.get(r.name)||{resource:r,direct:0,indirect:0,via:null};if(direct)t.direct+=count;else t.indirect+=count;if(via)t.via=via;totals.set(r.name,t)},steps=[];
 const walk=(r,count,direct,trail)=>{add(r,count,direct);const m=recipeForLevel(r,level);if(!m||trail.includes(r.name))return;const parts=m.per_unit.map(x=>({resource:R[x.resource_id],count:x.count*count})).filter(x=>x.resource);steps.push({resource:r,count,building:m,parts});for(const part of parts){walk(part.resource,part.count,false,[...trail,r.name])}};
 for(const w of wanted)walk(w.resource,w.count,true,[]);
 for(const st of steps){const t=totals.get(st.resource.name);if(t)t.via=st.building}
 return {totals:[...totals.values()].filter(t=>t.direct+t.indirect>0),steps}}
function objectiveNeedsSection(level){const s=level.scenario;if(!s)return '';const byObjective=sec=>{const m=new Map();for(const o of s.objectives.filter(x=>x.IsSecondary===sec&&['Have','Create'].includes(x.condition_name))){const r=objectiveResource(o);if(!r)continue;m.set(r.id,{resource:r,count:(m.get(r.id)?.count||0)+o.NeededAmount})}return [...m.values()]};
 const main=byObjective(false),optional=byObjective(true);if(!main.length&&!optional.length)return '';
 const mainRoll=expandNeeds(level,main),allRoll=expandNeeds(level,[...main,...optional]),round=n=>Math.round(n*100)/100,rlink=r=>`<a class="resource-link" href="${url('resources',r.id)}">${esc(r.name)}</a>`,blink=m=>`<a href="${url('buildings',m.building_id)}">${esc(m.building_name)}</a>`;
 const rows=[...allRoll.totals].sort((a,b)=>(b.direct>0)-(a.direct>0)||(b.direct+b.indirect)-(a.direct+a.indirect)).map(t=>{const mt=mainRoll.totals.find(x=>x.resource.name===t.resource.name),here=new Set((s.buildable_entries||[]).map(x=>x.gameobject_id));return `<tr><td>${icon('resources',t.resource)}${rlink(t.resource)}</td><td>${mt?fmt(round(mt.direct+mt.indirect)):'—'}</td><td>${fmt(round(t.direct+t.indirect))}</td><td>${t.direct?fmt(round(t.direct)):'—'}</td><td>${t.via?blink(t.via)+(here.has(t.via.building_id)?'':' <span class="objective-note">(not buildable on this map)</span>'):'<span class="unknown">gathered or traded</span>'}</td></tr>`}).join('');
 const chain=allRoll.steps.map(st=>`<li>${fmt(round(st.count))} ${rlink(st.resource)} at the ${blink(st.building)} needs ${st.parts.map(x=>`${fmt(round(x.count))} ${rlink(x.resource)}`).join(' + ')}</li>`).join('');
 return `<section class="rule-section" id="objective-needs"><h2>What the objectives need</h2><p>Items the objectives ask for, plus the ingredients to make them, worked back through each recipe${s.buildable_entries?.length?' using the buildings this map offers':''}. Amounts are ratios: round up to whole items and allow extra for anything villagers use along the way.</p><div class="table-wrap"><table><thead><tr><th>Resource</th><th>Main objectives</th><th>Main + optional</th><th>Of which asked for directly</th><th>Made at</th></tr></thead><tbody>${rows}</tbody></table></div><details><summary>How the totals were worked out</summary><ul class="recipe-steps">${chain}</ul></details><p class="small">Construction materials for the buildings themselves are not included yet. Recipe ratios come from each resource's stored recipe; see the resource pages for their evidence.</p></section>`}
function levelBody(o){const s=o.scenario;if(!s)return legacyLevelBody(o);const cfg=s.level_config[0]||{},needs=[['Food','Food'],['Housing','Housing'],['Community','Community'],['Entertainment','Fun'],['Heat','Heat'],['Wellness','Wellness'],['Refreshment','Cooling'],['Hydration','Hydration / thirst']];const build=[...new Map(s.buildable_entries.map(x=>[x.guid,x])).values()],plants=build.filter(x=>B[x.gameobject_id]?.is_plant||x.localization_key?.startsWith('Plant.')),other=build.filter(x=>!plants.includes(x));const objectiveTable=secondary=>{const os=s.objectives.filter(x=>x.IsSecondary===secondary);return os.length?`<div class="table-wrap"><table><thead><tr><th>Condition</th><th>Target</th><th>Required value</th><th>What counts</th></tr></thead><tbody>${os.map(scenarioObjective).join('')}</tbody></table></div>`:'<p>None.</p>'};const assetList=items=>items.length?'<ul>'+items.map(x=>'<li>'+scenarioAsset(x)+'</li>').join('')+'</ul>':'<p>No entries in this group.</p>';return `<div class="prose"><p>${rich(o.description)}</p></div><div class="tags">${tag('Decoded scenario')}${tag('Objectives cross-checked')}</div><p class="small">Stored map configuration for version 30, build 254. Packaged content does not establish live menu availability.</p><div class="fact-grid facts-4"><div class="fact"><small>Biome</small><b>${biomeCell(o)}</b></div><div class="fact"><small>Main objectives</small><b>${s.primary_objective_count}</b></div><div class="fact"><small>Optional objectives</small><b>${s.optional_objective_count}</b></div><div class="fact"><small>Day limit</small><b>${s.day_limit===-1?'No day limit':s.day_limit===null?'Not set':s.day_limit+' days'}</b></div></div>${startingConditions(s)}<section class="rule-section"><h2>Main objectives</h2>${objectiveTable(false)}<h2>Optional objectives</h2>${objectiveTable(true)}<p class="small">Values and comparisons match both the header and world records. Percentage units distinguish satisfaction, settled villagers and equipment from item counts. Settlement wording is supported by Level01B; Cliffside Resort separately says “Satisfy Housing”. “Consume / recycle” is an internal condition whose wording depends on the target.</p></section>${objectiveNeedsSection(o)}${strategySection(o)}<section class="rule-section"><h2>Villager needs</h2><div class="table-wrap"><table><thead><tr><th>Need</th><th>Active on this map</th></tr></thead><tbody>${needs.map(([key,label])=>{const k='IsConcern'+key+'Available';return `<tr><td>${label}</td><td>${Object.hasOwn(cfg,k)?cfg[k]?'Yes':'No':'Not set (older map)'}</td></tr>`}).join('')}</tbody></table></div><p class="small">An absent field in an older map is not treated as disabled. Runtime defaults and migration remain unverified.</p></section><section class="rule-section"><h2>Available buildings & plants</h2><p>${build.length} buildings and plants can be built on this map from the start. Anything unlocked during play is not included.</p><div class="biome-lists"><section class="panel"><h3>Buildings, structures & decorations</h3>${assetList(other)}</section><section class="panel"><h3>Fields & plants</h3>${assetList(plants)}</section></div></section><section class="rule-section"><h2>Starting objects & resources</h2><p class="small">Counts below are serialized prefab entities. They do not establish harvest yields, stockpile units, or numbers of independent buildings; child entities and internal objects can be included.</p><details><summary>Show ${s.initial_prefab_instances.length} starting object types</summary><div class="table-wrap"><table><thead><tr><th>Object</th><th>Count</th></tr></thead><tbody>${s.initial_prefab_instances.map(x=>`<tr><td>${scenarioAsset(x)}</td><td>${x.instance_count}</td></tr>`).join('')}</tbody></table></div></details></section>${source({text_asset_id:s.text_asset_id,source_level_path:s.source_level_path,sha256:s.sha256,world_objectives_match_header:s.world_objectives_match_header,level_config:s.level_config},'Scenario decoding evidence')}<section class="rule-section"><h2>Remaining checks</h2>${checks(['Confirm current menu category and release availability.','Check runtime unlocks and defaults for need fields absent in legacy maps.','Measure yields, need decay, production rates and other runtime effects.'])}</section>`}

function scenarioNeedSummary(s){const labels={Food:"Food",Housing:"Housing",Community:"Community",Entertainment:"Fun",Heat:"Heat",Wellness:"Wellness",Refreshment:"Cooling",Hydration:"Hydration"};return Object.entries(s.level_config[0]||{}).filter(([k,v])=>k.startsWith("IsConcern")&&v===true).map(([k])=>labels[k.slice(9,-9)]||k).join(", ")||"None"}

function biomeBody(o){const b=biomeRule(o);return `${o.id==='Winter'?observedBuilding({name:'Greenhouse'}):''}<section class="rule-section"><h2>Needs & environment</h2>${(b?.special_needs_and_hazards||[]).map(t=>`<p>${rich(t.text)}</p>`).join('')||'<p>See individual scenarios for their enabled needs.</p>'}</section><section class="rule-section"><h2>Plants & buildings</h2><p>Available plants and buildings depend on the scenario. Each scenario page lists its own planting and building options.</p><a href="${url('levels')}">Browse scenarios</a></section>${biomeSpawnSection(o)}${biomeLevelsSection(o)}${source(b,'Sandbox biome data — interpretation under review')}`;}
// Reader pages and research pages share one source renderer; research material is moved, not discarded.
function rawArticle(type,id){if(type==='buildings')return buildingPage(B[id]);if(type==='resources')return resourcePage(R[id]);if(type==='chains')return chainPage(B[id]);const list=type==='heroes'?W.leaders:W[type];return worldPage(type,list.find(x=>String(x.id)===String(id)))}
function pullBlocks(html,tagName,predicate){const re=new RegExp('<\\/?'+tagName+'\\b[^>]*>','gi'),stack=[],spans=[];let m;while((m=re.exec(html))){if(m[0].startsWith('</')){const begin=stack.pop();if(begin!==undefined){const text=html.slice(begin,re.lastIndex);if(predicate(text))spans.push([begin,re.lastIndex,text])}}else stack.push(m.index)}const top=spans.filter(s=>!spans.some(p=>p!==s&&p[0]<s[0]&&p[1]>=s[1])).sort((a,b)=>a[0]-b[0]);let clean='',pos=0;for(const [start,end]of top){clean+=html.slice(pos,start);pos=end}clean+=html.slice(pos);return {html:clean,blocks:top.map(x=>x[2])}}
function splitResearch(html){let notes=[];for(const [tag,pred] of [['details',s=>/^<details\b[^>]*class="source"/.test(s)],['aside',s=>/^<aside\b[^>]*class="detail-aside"/.test(s)],['section',s=>/^<section\b[^>]*>\s*<h2>(Pending verification|Gameplay checks|Remaining checks|What still needs checking|Biome assignments|Sandbox biome references|Content availability)<\/h2>/.test(s)],['div',s=>/^<div\b[^>]*class="notice\b/.test(s)]]){const out=pullBlocks(html,tag,pred);html=out.html;notes.push(...out.blocks)}
 const paragraphs=pullBlocks(html,'p',s=>/^<p\b[^>]*class="small"/.test(s)&&/verif|not tested|untested|decoded|stored map configuration|runtime|source tables|internal condition|not establish/i.test(s));html=paragraphs.html;notes.push(...paragraphs.blocks);
 html=html.replace(/<span class="tag[^"\n]*">(?:Needs gameplay verification|Decoded[^<]*|Recovered[^<]*|Objectives cross-checked|Unknown|Release unconfirmed|Sandbox configuration|No configuration decoded|Derived from[^<]*|Game text)<\/span>/g,'').replace(/<div class="tags">\s*<\/div>/g,'').replace(/<div><dt>(?:Work range \(raw units\)|Work schedule \(raw cycle\)|Gameplay verification|Game verification|Objective quantities|Internal name|Data version|Packaged map)<\/dt><dd>[\s\S]*?<\/dd><\/div>/g,'');
 return {html,notes};}
function readerArticle(html,type,id){const {html:clean}=splitResearch(html);const rec=pageLookup[type+'/'+id];return clean+`<p class="article-evidence-link"><a href="${url('evidence',type+'/'+id)}">Sources & research notes for this page</a></p>`+contributionLinks(type,id,rec?.name||'')}
function researchPage(id){const slash=id.indexOf('/'),type=id.slice(0,slash),key=id.slice(slash+1),rec=pageLookup[type+'/'+key];if(!rec)return empty();const original=rawArticle(type,key),split=splitResearch(original);let extra='';if(type==='buildings'){const b=B[key];extra=source({work_schedule:b.workplace_config?.WorkTimeRange,interpretation:'Normalized work-cycle interval; time origin and clock mapping unverified.'},'Work schedule fields');if(b.is_plant){const g=growthFor(b);if(g)extra+=`<section class="rule-section"><h2>Growth stages</h2><p>The sapling definition stores ${g.stages.length} stages totalling ${fmt(g.total_configured_stage_days)} days: ${esc(g.stages.map(x=>fmt(x.days_duration)).join(' + '))}. ${esc(g.caveat||'')} Nobody has timed this plant in play, so whether a stored day equals a clock day, and whether the last stage is the harvestable state or a wait before it, are open questions.</p>${source(g,'Sapling growth definition')}</section>`;extra+=biomeResearch(b)}extra+=productionModelResearch(b);if(b.gameplay){const g=b.gameplay;extra+=`<section class="rule-section"><h2>Gameplay facts and their evidence</h2>${g.recipe_per_cycle?`<p><strong>Recipe per cycle</strong> (${esc(g.recipe_per_cycle.status)}): ${esc(g.recipe_per_cycle.inputs.map(x=>`${fmt(x.count)} ${x.name}`).join(' + '))} → ${esc(g.recipe_per_cycle.outputs.map(x=>`${fmt(x.count)} ${x.name}`).join(' + '))}. ${esc(g.recipe_per_cycle.evidence.kind)}, ${esc(g.recipe_per_cycle.evidence.date)}: ${esc(g.recipe_per_cycle.evidence.reference)}</p>`:''}${g.output_capacity?`<p><strong>Output capacity</strong> (${esc(g.output_capacity.status)}): ${g.output_capacity.count} ${esc(g.output_capacity.name)}. ${esc(g.output_capacity.evidence.kind)}, ${esc(g.output_capacity.evidence.date)}: ${esc(g.output_capacity.evidence.reference)}</p>`:''}${source(g,'Gameplay block')}</section>`}
 if(b.name==='Clay Pit')extra+=`<h2>Do clay workers sleep in?</h2><p>The Clay Pit stores a work interval of 0 → 0.6 while 53 workplaces, including Farm and Bakery, store 0.9 → 0.5. The shift starts and finishes a tenth of a day later than the standard one and has the same length, which matches the community report of late risers. Quarry, Orchard and Foresters' Hub store 0 → 0.5: the same late start with a standard finish. Which clock hour fraction 0 corresponds to, and whether the crew also sleeps longer, have not been verified.</p>`;}
 return `${header(rec.name+' — sources & research','Evidence, decoding details and open questions for this article.','RESEARCH')}<p><a href="${url(type,key)}">← ${esc(rec.name)}</a></p>${split.notes.join('')}${extra}${contributionNotes(type,key)}${observationLink(type,key,rec.name)}`;}
function biomeResearch(b){const related=N.biomes.filter(n=>['crops','orchard_plants','forester_plants','placeables'].some(k=>n[k]?.some(x=>x.wiki_refs?.some(ref=>ref.id===b.source.path_id||ref.id===b.gameobject_id))));return `<section class="rule-section"><h2>Sandbox biome references</h2><p>These are references in sandbox configuration, not a verified crop-availability table. Shared defaults, exclusions, farm compatibility and runtime filtering still need interpretation.</p><ul>${related.map(n=>`<li>${esc(n.name)}</li>`).join('')}</ul>${source(related.map(n=>({biome:n.name,source:n.source,assignments:n.crops,exclusions:n.excluded_base_placeables})),'Sandbox assignment records')}</section>`}
function cropPage(b){const maps=W.levels.filter(l=>l.scenario?.buildable_entries.some(x=>x.gameobject_id===b.gameobject_id));const farm=D.buildings.find(x=>x.name==='Farm');return `${crumbs('buildings',b.name)}<div class="detail-head"><div class="detail-icon">${icon('buildings',b)}</div><div><p class="eyebrow">PLANT</p><h1>${esc(b.name)}</h1></div></div><article>${buildingInfobox(b)}${verifyBadge('buildings',b.gameobject_id)}<p>${({orchard:'An orchard tree',forestry:'A forestry tree',crop:'A field crop'})[plantKind(b)]}${yieldRow(b)?` that yields ${yieldRow(b)}`:plantYield(b)?` that yields ${plantYield(b)}`:''}. ${plantKind(b)==='crop'?`Planted and harvested on a ${plantedBy(b)}`:`Planted by the ${plantedBy(b)}${harvestedBy(b)?` and harvested by the ${harvestedBy(b)}`:''}`}.${growthText(b)?` It grows in ${growthText(b)}.`:''}</p>${b.description?`<div class="prose"><p>${rich(b.description)}</p></div>`:''}${maps.length?scenarioBacklinks(b):'<section class="rule-section"><h2>Where it can be planted</h2><p>No matching scenario planting list was found.</p></section>'}${source(b,'Plant definition')}${biomeResearch(b)}${historySection('buildings',b.gameobject_id)}${navbox('buildings',b)}</article>`}
function friendlyTerm(key){const base=key.split('.').slice(0,2).join('.'),plural=/Plural/.test(key);return W.terms?.[key]||W.terms?.[base+(plural?'.NamePlural':'.Name')]||null}
function rich(s){return esc(s||'').replace(/&lt;\/?(?:style(?:=[^&]*?)?|size(?:=[^&]*?)?)&gt;/g,'').replace(/&lt;(\/?)b&gt;/g,'<$1strong>').replace(/\n/g,'<br>').replace(/\{([^}]+)\}|\[((?:Resource|Building|Sources|Field|Tree)\.[^\]]+)\]/g,(_,a,b)=>{const key=a||b,base=key.split('.').slice(0,2).join('.'),label=friendlyTerm(key);if(Bkey[base])return `<a class="resource-link" href="${url('buildings',Bkey[base].gameobject_id)}">${esc(Bkey[base].name)}</a>`;if(Rkey[base])return `<a class="resource-link" href="${url('resources',Rkey[base].id)}">${esc(label||Rkey[base].name)}</a>`;if(label)return esc(label);if(/count|amount|days|value|percentage/i.test(key))return 'target quantity';return esc(key.replace(/\.(WithIconPlural|WithIcon|NamePlural|Name)$/,'').split('.').at(-1).replace(/([a-z])([A-Z])/g,'$1 $2'))})}

function contributionNotes(type,id){const rows=(W.contributions||[]).filter(x=>x.target.type===type&&String(x.target.id)===String(id));return rows.length?`<section class="rule-section"><h2>Contributed observations</h2>${rows.map(x=>`<article><h3>${esc(x.claim)}</h3><p>Status: ${esc(x.status)} · ${esc(x.evidence.kind)} · ${esc(x.evidence.game_version)}</p><p>${esc(x.evidence.reference)}</p><p>${esc(x.notes||'')}</p></article>`).join('')}</section>`:''}
function contributionPage(){function inline(s){return esc(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\((https:\/\/[^)]+)\)/g,'<a href="$2">$1</a>')}let html='',list='';for(const line of W.contribution_guide.split('\n')){const ordered=/^\d+\. /.test(line),bullet=/^- /.test(line);if(!ordered&&!bullet&&list){html+=`</${list}>`;list=''}if(/^# /.test(line)){html+=header(line.slice(2),'Help improve a sourced, community-maintained reference.','CONTRIBUTE')}else if(/^## /.test(line)){html+=`<h2>${inline(line.slice(3))}</h2>`}else if(ordered||bullet){const wanted=ordered?'ol':'ul';if(list!==wanted){if(list)html+=`</${list}>`;html+=`<${wanted}>`;list=wanted}html+=`<li>${inline(line.replace(/^(?:- |\d+\. )/,''))}</li>`}else if(line.trim())html+=`<p>${inline(line)}</p>`}if(list)html+=`</${list}>`;return '<div class="prose contribution-guide">'+html+'</div>'}

let fullWorld,publicWorld,fullBiomes,publicBiomes,fullRules,publicRules;
function spoilerEntry(type,id){if(type==='chains')type='buildings';const entries=(fullWorld||W)?.spoiler_policy?.entries||[];return entries.find(x=>x.type===type&&String(x.id)===String(id));}
function initializeSpoilers(){fullRules=D;fullWorld=W;fullBiomes=N;publicRules={...D,buildings:D.buildings.filter(b=>!spoilerEntry('buildings',b.gameobject_id)&&!isSuppressed('buildings',b.gameobject_id)),resources:D.resources.filter(r=>!spoilerEntry('resources',r.id))};publicWorld={...W,levels:W.levels.filter(x=>!spoilerEntry('levels',x.id)),leaders:W.leaders.filter(x=>!spoilerEntry('heroes',x.id)),biomes:W.biomes.filter(x=>!spoilerEntry('biomes',x.id)),campaigns:W.campaigns.map(x=>({...x,level_ids:x.level_ids.filter(id=>!spoilerEntry('levels',id))})),stories:W.stories.filter(x=>!W.spoiler_policy.entries.some(e=>e.type==='heroes'&&(x.id===W.leaders.find(l=>l.id===e.id)?.name||x.name.includes(W.leaders.find(l=>l.id===e.id)?.name)))),ui_observations:{...W.ui_observations,availability:'Additional packaged content is listed separately in the Spoilers section.'}};publicBiomes={...N,biomes:N.biomes.filter(x=>!spoilerEntry('biomes',x.id))};}
function applySpoilerScope(type,id){const research=type==='evidence'?spoilerEntry(id.split('/')[0],id.slice(id.indexOf('/')+1)):null;const allow=type==='spoilers'||spoilerEntry(type,id)||research;W=allow?fullWorld:publicWorld;N=allow?fullBiomes:publicBiomes;D=allow?fullRules:publicRules;}
function spoilerWarning(type,id){const e=spoilerEntry(type,id);return `<aside class="notice"><div><strong>Spoilers: unreleased or release-unconfirmed content</strong><p>${esc(e.reason)} Status recorded ${esc(e.as_of)}.</p><a href="${url('spoilers')}">Spoiler index</a> · <a href="${url('')}">Return to the regular guide</a></div></aside>`;}
function spoilersHomeSection(){return `<section class="rule-section spoiler-home"><h2>Spoilers</h2><p>Looking to look ahead? Check out the spoilers section.</p><a href="${url('spoilers')}">Browse Spoilers →</a></section>`;}
function spoilersPage(){return `${header('Spoilers','This section contains reported-unreleased content and closely associated material whose release is unconfirmed. Names and details below may spoil future updates.','OPTIONAL CONTENT')}<p>Placement here is editorial; it does not establish a release date. Other entries with unknown release status are not automatically treated as unreleased.</p><p><a href="${url('')}">Return to the regular guide</a></p>${['resources','buildings','chains','heroes','levels','biomes','tournament'].map(type=>{const entries=fullWorld.spoiler_policy.entries.filter(x=>x.type===type);if(!entries.length)return '';return `<section class="rule-section"><h2>${({resources:'Resources & food',buildings:'Buildings',chains:'Production chains',heroes:'Leaders',levels:'Scenarios',biomes:'Biomes',tournament:'Tournament seasons'})[type]}</h2><ul>${entries.map(e=>{const obj=type==='tournament'?{name:tournamentText(`FastMode.${e.id}.Name`)||e.id}:(['buildings','chains'].includes(type)?fullRules.buildings:type==='resources'?fullRules.resources:type==='heroes'?fullWorld.leaders:fullWorld[type]).find(x=>String(x.gameobject_id||x.id)===String(e.id));return `<li><a href="${type==='tournament'?url('tournament','seasons'):url(type,e.id)}">${esc(obj.name)}</a> — ${esc(e.status==='reported-unreleased'?'Reported unreleased':'Related content; release unconfirmed')}<p>${esc(e.reason)}</p></li>`}).join('')}</ul></section>`}).join('')}`;}

// Companion-layer helpers: infoboxes, backlinks, grouped availability, story context, navboxes and contribution links.
const GITHUB='https://github.com/kellan/outlanders2-wiki';
const CATEGORY_LABELS={production:'Production building',homes:'Housing',fields:'Field or plant',other:'Structure or decoration'};
function contentFile(type,id){const folder={buildings:'buildings',chains:'buildings',resources:'resources',levels:'scenarios',heroes:'leaders',biomes:'biomes'}[type];return folder?`content/${folder}/${id}.json`:null}
function storyOf(levelId){return W.stories.find(s=>s.level_ids?.includes(levelId))}
function campaignOf(levelId){return W.campaigns.find(c=>c.level_ids.includes(levelId))}
function levelLink(l,extra=''){return `<a href="${url('levels',l.id)}">${esc(l.name)}</a>${extra}`}
function levelGroups(levels,extra=()=>''){
 const byId=new Map(levels.map(l=>[l.id,l]));const groups=[];const seen=new Set();
 for(const c of W.campaigns){const stories=W.stories.filter(s=>s.campaign_id===c.id).sort((a,b)=>a.menu_order-b.menu_order);const rows=[];
  for(const s of stories){const hits=(s.level_ids||[]).filter(i=>byId.has(i));if(!hits.length)continue;hits.forEach(i=>seen.add(i));rows.push(`<li><strong>${esc(s.name)}</strong>: ${hits.map(i=>levelLink(byId.get(i),extra(byId.get(i)))).join(', ')}</li>`)}
  const loose=c.level_ids.filter(i=>byId.has(i)&&!seen.has(i));if(loose.length){loose.forEach(i=>seen.add(i));rows.push(`<li><strong>Other levels</strong>: ${loose.map(i=>levelLink(byId.get(i),extra(byId.get(i)))).join(', ')}</li>`)}
  if(rows.length)groups.push({title:`<a href="${url('campaigns',c.id)}">${esc(c.name)}</a>`,html:`<ul class="level-groups">${rows.join('')}</ul>`,count:rows.length})}
 const rest=levels.filter(l=>!seen.has(l.id)),named=rest.filter(l=>!/^Unnamed scenario/.test(l.name)&&l.category!=='tournament_tutorial'),tutorials=rest.filter(l=>l.category==='tournament_tutorial'),unnamed=rest.filter(l=>/^Unnamed scenario/.test(l.name)&&l.category!=='tournament_tutorial');
 const links=ls=>`<div class="reference-links">${ls.sort((a,b)=>a.name.localeCompare(b.name)).map(l=>levelLink(l,extra(l))).join('')}</div>`;
 if(named.length)groups.push({title:'Standalone &amp; challenge maps',html:links(named)});
 if(tutorials.length)groups.push({title:'Tutorials',html:links(tutorials)});
 if(unnamed.length)groups.push({title:'',html:`<details><summary>${unnamed.length} unnamed archive map${unnamed.length>1?'s':''}</summary>${links(unnamed)}</details>`});
 return groups;
}
function groupedLevels(levels,extra){return levelGroups(levels,extra).map(g=>`${g.title?`<h3>${g.title}</h3>`:''}${g.html}`).join('')}
function objectiveTargets(predicate){const rows=[];for(const l of W.levels){const os=(l.scenario?.objectives||[]).filter(o=>['Have','Create','Consume','Extract','HaveInBuilding','GearedPercentage','UseSocialSpot'].includes(o.condition_name)&&predicate(o));if(os.length)rows.push({level:l,objectives:os})}return rows}
function objectiveText(o){const kinds={Have:'Have',Create:'Create',Consume:'Consume',Extract:'Extract',HaveInBuilding:'Have in building',GearedPercentage:'Equipped villagers',UseSocialSpot:'Use'},comparison={Equal:'=',NotEqual:'≠',Less:'<',LessOrEqual:'≤',Greater:'>',GreaterOrEqual:'≥'};return `${kinds[o.condition_name]||o.condition_name} ${comparison[o.comparison_name]||''} ${fmt(o.NeededAmount)}${o.IsSecondary?' (optional)':''}`}
function objectiveBacklinks(label,rows){if(!rows.length)return '';const byId=new Map(rows.map(r=>[r.level.id,r]));return `<section class="rule-section"><h2>Level objectives that need ${esc(label)}</h2><p class="small">Required amounts as set in each of ${rows.length} level${rows.length>1?'s':''}.</p>${groupedLevels(rows.map(r=>r.level),l=>` <span class="objective-note">${byId.get(l.id).objectives.map(objectiveText).map(esc).join('; ')}</span>`)}</section>`}
function plantKind(b){return b.paths.some(p=>p.includes('/orchard/'))?'orchard':b.paths.some(p=>p.includes('/forester/'))?'forestry':'crop'}
function plantedBy(b){const name={orchard:'Orchard',forestry:"Foresters' Hub",crop:'Farm'}[plantKind(b)];const x=D.buildings.find(o=>o.name===name&&!o.is_plant);return x?`<a href="${url('buildings',x.gameobject_id)}">${esc(x.name)}</a>`:esc(name)}
function plantYield(b){const outs=[...new Set(b.formula_ids.flatMap(i=>F[i]?.outputs.map(o=>o.resource_id)||[]))].map(id=>R[id]).filter(Boolean);return outs.length?outs.map(r=>`<a href="${url('resources',r.id)}">${esc(r.name)}</a>`).join(', '):null}
function joinNames(items,word='or'){return items.length>1?items.slice(0,-1).join(', ')+' '+word+' '+items[items.length-1]:items[0]||''}
function harvestedBy(b){if(plantKind(b)==='crop')return plantedBy(b);const cats=new Set(b.formula_ids.flatMap(i=>F[i]?.resource_source_category_ids||[]));if(!cats.size)return null;const hs=uniq(D.buildings.filter(o=>!o.is_plant&&!isSuppressed('buildings',o.gameobject_id)&&o.formula_ids.some(i=>F[i]?.resource_source_category_ids.some(c=>cats.has(c)))));return hs.length?joinNames(hs.map(o=>`<a href="${url('buildings',o.gameobject_id)}">${esc(o.name)}</a>`)):null}
function growthText(b){const g=growthFor(b);if(!g)return null;const d=g.total_configured_stage_days,n=g.stages.length;return `${fmt(d)} day${d===1?'':'s'} (${n} stage${n===1?'':'s'})`}
function growthFor(b){const norm=s=>String(s).replace(/^Field\s*/,'').replace(/\s*Sapling\s*/,'').replace(/\s+/g,'').toLowerCase().replace(/tree$/,'');return D.growth?.find(g=>norm(g.name)===norm(b.internal_name))}
function infobox(type,o,rows,image){const body=rows.filter(r=>r&&r[1]!==null&&r[1]!==undefined&&r[1]!=='').map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${v}</dd></div>`).join('');return `<aside class="infobox"><div class="infobox-image">${image}</div><h3 class="infobox-title">${esc(o.name)}</h3><dl>${body}</dl></aside>`}
function buildingInfobox(b){const cat=category(b),recipe=b.derived_recipes.find(r=>!r.caveats.length),cycle=cycleRecipe(b),cap=b.gameplay?.output_capacity,guide=W.ui_observations?.buildings?.[b.name],maps=W.levels.filter(l=>l.scenario?.buildable_entries.some(x=>x.gameobject_id===b.gameobject_id)),growth=growthFor(b);
 const plantKind=b.paths.some(p=>p.includes('/orchard/'))?'Orchard plant':b.paths.some(p=>p.includes('/forester/'))?'Forestry plant':'Field crop';
 if(b.is_plant)return infobox('buildings',b,[['Type',plantKind],['Yields',yieldRow(b)||plantYield(b)],['Planted by',plantedBy(b)],['Harvested by',harvestedBy(b)],['Grows in',growthText(b)],['Levels',maps.length?`<a href="#level-availability">${maps.length} level${maps.length>1?'s':''}</a>`:null]],icon('buildings',b));
 return infobox('buildings',b,[['Type',CATEGORY_LABELS[cat]],['Footprint',!b.is_plant&&b.dimensions?`${fmt(b.dimensions.x)} × ${fmt(b.dimensions.z)}`:null],['Cost',!b.is_plant&&b.construction?.material_inputs.length?inlineAmounts(b.construction.material_inputs):null],['Workers',b.max_workers],['Houses',b.sleep_spots!==null?`${b.sleep_spots} villagers`:null],['Work hours',shiftRow(b)],['Harvests from',harvestRow(b)],['Visiting gives',socialRow(b)],['Reported output',reportedRateRow(b)],['Placement',placementRow(b)],['Recipe',cycle?`${inlineAmounts(cycle.inputs)} → ${inlineAmounts(cycle.outputs)} <span class="objective-note">${recipeLabel(cycle)}</span>`:b.formula_ids.length?`<a href="${url('chains',b.gameobject_id)}">See production chain</a>`:null],['Capacity',cap?`${cap.count} ${esc(cap.name)} <span class="objective-note">(${cap.status==='disputed'?'disputed: ':''}${esc(cap.evidence.kind.replace('-',' '))})</span>`:null],['Growth',growth?`${growth.total_configured_stage_days} day${growth.total_configured_stage_days===1?'':'s'} across ${growth.stages.length} stage${growth.stages.length===1?'':'s'} <span class="objective-note">stored durations, not timed in play</span>`:null],['Levels',maps.length?`<a href="#level-availability">${maps.length} level${maps.length>1?'s':''}</a>`:null]],icon('buildings',b))}
function resourceInfobox(r,producing,using,costs,objectives){const vals=Object.entries(r.need_units).filter(([,v])=>v!==0);const list=bs=>uniq(bs).slice(0,6).map(b=>`<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a>`).join(', ')+(uniq(bs).length>6?` and ${uniq(bs).length-6} more`:'');
 return infobox('resources',r,[['Type',r.publicly_named?(r.need_units.FoodUnits>0?'Food':'Resource'):'Intermediate'],['Satisfies',(vals.length||resourceStatedEffects(r).length)?[...vals.map(([k,v])=>`<a href="${url('needs')}#need-${slug(k==='EntertainmentUnits'?'Fun':k==='RefreshmentUnits'?'Cooling':k.replace('Units',''))}">${esc(k==='EntertainmentUnits'?'Fun':k==='RefreshmentUnits'?'Cooling':k.replace('Units',''))}</a> ${fmt(v)}`),...resourceStatedEffects(r).map(e=>{const v=socialNeedValue(e.building,e.need);return `<a href="${url('needs')}#need-${slug(e.need)}">${esc(e.need)}</a> ${v!==null?fmt(v)+' <span class="objective-note">(at the '+esc(e.building.name)+')</span>':'<span class="objective-note">(stated, amount unknown)</span>'}`})].join(', '):null],['Consumed by',adultsOnly(r)?'Adults only':null],['Gear effect',gearRow(r)],['Made from',r.made_from?.length?r.made_from.map(m=>`${perUnitText(m.per_unit,r.name)} <span class="objective-note">(each, at the ${esc(m.building_name)})</span>`).join('<br>'):null],['Produced by',producing.length?list(producing):null],['Used by',using.length?list(using):null],['Builds',costs.length?list(costs):null],['Objectives',objectives.length?`<a href="#objective-backlinks">${objectives.length} level${objectives.length>1?'s':''}</a>`:null]],icon('resources',r))}
function verifyBadge(type,id,extra=''){return `<p class="verify-badge"><span>Game data v30 · build 254</span>${extra}<a href="${url('evidence',type+'/'+id)}">Sources &amp; research notes</a></p>`}
function contributionLinks(type,id,name){const file=contentFile(type,id);if(!file)return '';const spoiler=!!spoilerEntry(type,id);const title=encodeURIComponent(spoiler?'Correction for a spoiler entry':`Correction: ${name}`);const page=spoiler?'':`&amp;page=${encodeURIComponent(name)}`;return `<p class="article-actions"><a href="${GITHUB}/edit/main/${file}">Suggest an edit</a><a href="${GITHUB}/issues/new?template=content-correction.yml&amp;title=${title}${page}">Report a problem</a><a href="${GITHUB}/blob/main/CONTRIBUTING.md">How contributions work</a></p>`}
function observationLink(type,id,name){const spoiler=!!spoilerEntry(type,id);const title=encodeURIComponent(spoiler?'Observation about a spoiler entry':`Observation: ${name}`);return `<p class="article-actions"><a href="${GITHUB}/issues/new?template=gameplay-observation.yml&amp;title=${title}${spoiler?'':`&amp;target=${encodeURIComponent(name)}`}">Report a gameplay observation</a><a href="${GITHUB}/blob/main/CONTRIBUTING.md#evidence-and-uncertainty">What counts as evidence</a></p>`}
function navboxList(label,items,type){return items.length?`<div class="navbox-row"><span class="navbox-label">${label}</span><ul>${items.map(o=>`<li><a href="${url(type,o.gameobject_id||o.id)}">${esc(o.name)}</a></li>`).join('')}</ul></div>`:''}
function navbox(type,o){const sorted=xs=>[...xs].sort((a,b)=>a.name.localeCompare(b.name));let title='',rows='';
 if(type==='buildings'||type==='chains'){const cat=category(o);const same=uniq(D.buildings.filter(b=>!isSuppressed('buildings',b.gameobject_id)&&!b.is_plant&&category(b)===cat));title=CATEGORY_LABELS[cat]+'s';if(o.is_plant){const plants=uniq(D.buildings.filter(b=>b.is_plant&&!isSuppressed('buildings',b.gameobject_id)&&b.name!=='Template'));title='Fields & plants';rows=navboxList('Crops',sorted(plants.filter(p=>p.paths.some(x=>x.includes('/buildings/field/')))),'buildings')+navboxList('Orchard',sorted(plants.filter(p=>p.paths.some(x=>x.includes('/orchard/')))),'buildings')+navboxList('Forestry',sorted(plants.filter(p=>p.paths.some(x=>x.includes('/forester/')))),'buildings')}else rows=navboxList(title,sorted(same),'buildings')}
 if(type==='resources'){const food=o.publicly_named&&o.need_units.FoodUnits>0;const items=uniq(D.resources.filter(r=>r.publicly_named&&(food?r.need_units.FoodUnits>0:r.need_units.FoodUnits===0)));title=food?'Food':'Resources';rows=navboxList(title,sorted(items),'resources')}
 if(type==='heroes'){title='Leaders';rows=navboxList('Leaders',sorted(W.leaders),'heroes')}
 if(type==='biomes'){title='Biomes';rows=navboxList('Biomes',sorted(W.biomes),'biomes')}
 if(type==='levels'){const s=storyOf(o.id),c=campaignOf(o.id);if(s&&c){title=esc(c.name);rows=navboxList(esc(s.name),s.level_ids.map(i=>W.levels.find(l=>l.id===i)).filter(Boolean),'levels');const others=W.stories.filter(x=>x.campaign_id===c.id&&x!==s).sort((a,b)=>a.menu_order-b.menu_order);rows+=others.length?`<div class="navbox-row"><span class="navbox-label">Other stories</span><ul>${others.map(x=>`<li><a href="${url('campaigns',c.id)}">${esc(x.name)}</a></li>`).join('')}</ul></div>`:''}}
 return rows?`<nav class="navbox" aria-label="Related pages"><h2>${title}</h2>${rows}</nav>`:''}
function storyContext(o){const s=storyOf(o.id),c=campaignOf(o.id);if(!s||!c)return o.category==='tournament_tutorial'?'<p class="story-context">Tournament tutorial level.</p>':'';const ids=s.level_ids,pos=ids.indexOf(o.id),prev=pos>0?W.levels.find(l=>l.id===ids[pos-1]):null,next=pos<ids.length-1?W.levels.find(l=>l.id===ids[pos+1]):null,leader=W.leaders.find(l=>l.name===s.leader_name);
 return `<div class="story-context"><p><a href="${url('campaigns',c.id)}">${esc(c.name)}</a> › <strong>${esc(s.name)}</strong> · Level ${pos+1} of ${ids.length}${leader?` · Leader: <a href="${url('heroes',leader.id)}">${esc(leader.name)}</a>`:''}</p><p class="story-nav">${prev?`<a href="${url('levels',prev.id)}">← ${esc(prev.name)}</a>`:'<span></span>'}${next?`<a href="${url('levels',next.id)}">${esc(next.name)} →</a>`:''}</p></div>`}
function leaderStories(o){const stories=W.stories.filter(s=>s.leader_name===o.name&&s.level_ids?.length).sort((a,b)=>a.campaign_id.localeCompare(b.campaign_id)||a.menu_order-b.menu_order);if(!stories.length)return '';return `<section class="rule-section"><h2>Stories &amp; levels</h2>${stories.map(s=>{const c=W.campaigns.find(c=>c.id===s.campaign_id);return `<h3>${esc(s.name)}${c?` <small class="small"><a href="${url('campaigns',c.id)}">${esc(c.name)}</a></small>`:''}</h3><ol class="story-levels">${s.level_ids.map(i=>W.levels.find(l=>l.id===i)).filter(Boolean).map(l=>`<li>${levelLink(l)}${l.scenario?` <span class="objective-note">${l.scenario.primary_objective_count} main objective${l.scenario.primary_objective_count===1?'':'s'}${l.scenario.day_limit>0?` · ${l.scenario.day_limit} days`:''}</span>`:''}</li>`).join('')}</ol>`}).join('')}</section>`}

// Work schedules: WorkplaceConfig.WorkTimeRange stores a start and end as fractions of a day (wrapping past 1.0). Most workplaces use 0.9 → 0.5; differences are reported relative to that standard shift. The clock mapping of 0.0 is unresolved.
const STANDARD_SHIFT={start:0.9,end:0.5};
function shiftLength(s,e){const l=((e-s)%1+1)%1;return l||1}
function shiftInfo(b){const r=b.workplace_config?.WorkTimeRange;if(!r)return null;const s=+r.Start.toFixed(3),e=+r.End.toFixed(3),off=v=>+((((v+0.5)%1)+1)%1-0.5).toFixed(3),startOff=off(s-STANDARD_SHIFT.start),endOff=off(e-STANDARD_SHIFT.end),length=shiftLength(s,e);
 const amount=v=>{const a=Math.abs(v);return a===0.1?'a tenth of a day':a===0.05?'a twentieth of a day':`${fmt(a)} of a day`};const parts=[];
 if(startOff>0)parts.push(`starts ${amount(startOff)} later`);if(startOff<0)parts.push(`starts ${amount(startOff)} earlier`);if(endOff>0)parts.push(`finishes ${amount(endOff)} later`);if(endOff<0)parts.push(`finishes ${amount(endOff)} earlier`);
 return {start:s,end:e,length,startOff,endOff,standard:!parts.length,label:parts.length?parts.join(', '):'Standard hours'}}
function shiftRow(b){const i=shiftInfo(b);return i?`${esc(i.label)} <span class="objective-note">${fmt(Math.round(i.length*100))}% of the day</span>`:null}
function workSchedulesSection(){const groups=new Map();for(const b of uniq(D.buildings.filter(b=>b.workplace_config&&!isSuppressed('buildings',b.gameobject_id)))){const i=shiftInfo(b),k=`${i.start}→${i.end}`;if(!groups.has(k))groups.set(k,{info:i,buildings:[]});groups.get(k).buildings.push(b)}
 const rows=[...groups.values()].sort((a,b)=>b.buildings.length-a.buildings.length).map(g=>`<tr><td>${fmt(g.info.start)} → ${fmt(g.info.end)}</td><td>${esc(g.info.label)}</td><td>${fmt(Math.round(g.info.length*100))}%</td><td>${g.buildings.sort((a,b)=>a.name.localeCompare(b.name)).map(b=>`<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a>`).join(', ')}</td></tr>`).join('');
 return `<section class="rule-section" id="work-schedules"><h2>Work schedules</h2><p>Each workplace stores a shift as a start and end fraction of the day. A game day is ${fmt(RF.seconds_per_day)} simulation seconds at normal speed, so the standard shift lasts ${fmt(Math.round(RF.seconds_per_day*0.6))} seconds and a tenth of a day is ${fmt(RF.seconds_per_day/10)} seconds. Most workplaces run the same standard shift; a few start or finish later, which is why some crews are seen leaving for work after everyone else. Which clock hour the fraction 0 corresponds to has not been established.</p><div class="table-wrap"><table><thead><tr><th scope="col">Stored shift</th><th scope="col">Compared with the standard shift</th><th scope="col">Share of the day</th><th scope="col">Workplaces</th></tr></thead><tbody>${rows}</tbody></table></div></section>`}

// Level strategies: community advice stored in content/strategies/<levelId>.json, contributed through the level-strategy issue form and rendered apart from decoded facts.
function strategyFormUrl(o){const spoiler=!!spoilerEntry('levels',o.id);const title=encodeURIComponent(spoiler?'Strategy for a spoiler level':`Strategy: ${o.name}`);return `${GITHUB}/issues/new?template=level-strategy.yml&amp;title=${title}${spoiler?'':`&amp;level=${encodeURIComponent(o.name)}`}`}
function strategySection(o){const s=(W.strategies||[]).find(x=>x.id===o.id);const share=`<p class="article-actions"><a href="${strategyFormUrl(o)}">${s?'Suggest a change to this strategy':'Share a strategy for this level'}</a><a href="${GITHUB}/blob/main/CONTRIBUTING.md#share-a-level-strategy">How strategies are reviewed</a></p>`;
 if(!s)return `<section class="rule-section strategy"><h2>Strategy</h2><p>No community strategy has been recorded for this level yet. If you have finished it, the form takes a build order, what to watch out for, and the game version; a maintainer turns it into a page section.</p>${share}</section>`;
 const steps=s.build_order.map(step=>{const b=B[step.gameobject_id];return `<li>${b?`<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a>`:esc(step.name||'Unknown building')}${step.note?` <span class="objective-note">${esc(step.note)}</span>`:''}</li>`}).join('');
 return `<section class="rule-section strategy"><h2>Strategy <span class="tag ${s.status==='reviewed'?'':'amber'}">${s.status==='reviewed'?'Community · reviewed':'Community · draft'}</span></h2><p>${esc(s.summary)}</p>${steps?`<h3>Suggested build order</h3><ol class="story-levels">${steps}</ol>`:''}${s.pitfalls?.length?`<h3>Watch out for</h3><ul class="check-list">${s.pitfalls.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:''}<p class="objective-note">Contributed by ${esc(s.contributor)} · game version ${esc(s.game_version)} · ${esc(s.date)}${s.source?` · ${esc(s.source)}`:''}. Community advice, not decoded data.</p>${share}</section>`}

// Version history: content/history.json holds dated, evidenced changes per entity. Entries render as a History section on entity pages and as a site Changelog grouped by game version.
function historyEntries(type,id){return ((fullWorld||W).history?.entries||[]).filter(e=>e.type===type&&String(e.id)===String(id)).sort((a,b)=>b.date.localeCompare(a.date))}
function historySection(type,id){const rows=historyEntries(type,id);if(!rows.length)return '';return `<section class="rule-section history"><h2>History</h2><table class="history-table"><tbody>${rows.map(e=>`<tr><td><strong>Update ${esc(e.game_version)}</strong><br><span class="objective-note">${esc(e.date)}</span></td><td>${esc(e.change)} <span class="objective-note">${esc(e.evidence.kind.replace('-',' '))}${e.evidence.url?` · <a href="${esc(e.evidence.url)}">link</a>`:''}</span></td></tr>`).join('')}</tbody></table></section>`}
function historyTargetLink(e){const type=e.type;const list=type==='buildings'?D.buildings:type==='resources'?D.resources:type==='heroes'?W.leaders:W[type];const o=list?.find(x=>String(x.gameobject_id??x.id)===String(e.id));return o?`<a href="${url(type,e.id)}">${esc(o.name)}</a>`:null}
function changelogPage(){const h=W.history||{entries:[]};const visible=h.entries.filter(e=>!spoilerEntry(e.type,e.id)).map(e=>({...e,link:historyTargetLink(e)})).filter(e=>e.link);const groups=new Map();for(const e of visible){const k=e.game_version;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(e)}
 const versions=[...groups.keys()].sort((a,b)=>(parseFloat(b)||0)-(parseFloat(a)||0));
 return `${header('Changelog','What changed in each game update, as far as the wiki can establish it. Entries carry their evidence; the current data baseline is version 30, build 254.','VERSION HISTORY')}<p>${h.baseline?esc(h.baseline):''} Earlier updates are backdated only where an official source or decoded marker ties content to an update. Future builds are compared with <code>scripts/compare-content.mjs</code>, and reviewed differences are added here.</p>${versions.map(v=>{const rows=groups.get(v);const date=rows.map(r=>r.date).sort()[0];return `<section class="rule-section"><h2>Update ${esc(v)} <span class="objective-note">${esc(date)}</span></h2><ul class="check-list">${rows.map(e=>`<li>${e.link}: ${esc(e.change)} <span class="objective-note">${esc(e.evidence.kind.replace('-',' '))}${e.evidence.url?` · <a href="${esc(e.evidence.url)}">link</a>`:''}</span></li>`).join('')}</ul></section>`}).join('')||'<p>No dated changes have been recorded yet.</p>'}`}

// Stored-configuration additions: level biome from the scene name, starting conditions from prefab instances, need satisfiers from resource units, age limits, harvest sources and placement rules.
const SCENE_BIOME={LevelSnow:['Winter',''],LevelSnowPrecipice:['Winter','precipice scene'],LevelTropical:['Tropical',''],Level:['Green',''],LevelDesert:['Desert',''],LevelSwamp:['Swamp',''],LevelHalloween:['Halloween',''],LevelChristmas:['Winter','Christmas event scene']};
function levelBiome(l){const scene=l.scenario?.level_config?.[0]?.LevelScene;if(!scene)return null;const m=SCENE_BIOME[scene];if(!m)return {scene,label:scene};const biome=(fullWorld||W).biomes.find(b=>b.id===m[0]);const visible=W.biomes.find(b=>b.id===m[0]);return {scene,biome:visible||null,label:biome?.name||m[0],note:m[1]}}
function biomeCell(l){const b=levelBiome(l);if(!b)return '<span class="unknown">Not recorded</span>';return (b.biome?`<a href="${url('biomes',b.biome.id)}">${esc(b.label)}</a>`:esc(b.label))+(b.note?` <span class="objective-note">${esc(b.note)}</span>`:'')}
function biomeLevelsSection(o){const levels=W.levels.filter(l=>levelBiome(l)?.label===o.name);if(!levels.length)return '';return `<section class="rule-section"><h2>Levels in this biome</h2><p>${levels.length} level${levels.length>1?'s':''} store a ${esc(o.name)} scene. The scene name is stored map configuration; it does not by itself establish which crops or hazards are active.</p>${groupedLevels(levels)}</section>`}
function biomeSpawnSection(o){const b=biomeRule(o);const rows=(b?.resource_sources||[]).filter(x=>!/fish|decor|cosmetic/i.test(x.asset_path)&&x.density>0);if(!rows.length)return '';const kind={Rocks:'rock',WoodTrees:'wood',FruitTrees:'fruit',Trees:'wood',Reed:'reed'};return `<section class="rule-section"><h2>Map resources</h2><p>What the map generator scatters in this biome and how densely. Story and challenge maps are hand-made and can differ.</p><div class="table-wrap"><table><thead><tr><th scope="col">Source</th><th scope="col">Yields</th><th scope="col">Spawn density</th></tr></thead><tbody>${rows.sort((a,b)=>b.density-a.density).map(x=>`<tr><td>${assignedLink(x)}</td><td>${esc(kind[x.spawn_key]||x.spawn_key||'—')}${x.food_source_flag?' (food)':''}</td><td>${fmt(+x.density.toFixed(3))}</td></tr>`).join('')}</tbody></table></div></section>`}
function startingConditions(s){const items=s.initial_prefab_instances||[];const villagers={adults:0,kids:0,elders:0,babies:0};const stock=[],built=[],tools=[],other=[];
 for(const x of items){const n=x.name||'';if(/Villager/.test(n)){if(/Kid/.test(n))villagers.kids+=x.instance_count;else if(/Old|Elder/.test(n))villagers.elders+=x.instance_count;else if(/Baby/.test(n))villagers.babies+=x.instance_count;else villagers.adults+=x.instance_count;continue}
  const b=B[x.gameobject_id],r=Rkey[x.localization_key]||D.resources.find(r=>r.publicly_named&&(r.name===n||r.internal_name===n));
  if(b&&!b.is_plant)built.push({name:b.name,id:b.gameobject_id,count:x.instance_count});else if(r)stock.push({name:r.name,id:r.id,count:x.instance_count});else if(/^(Hoe|Axe|Scythe|Pick|Shovel|Hammer|Wheelbarrow|SeedBag|Tool|Bucket|Saw)\b/i.test(n))tools.push({name:n.replace(/\s*-\s*/,' · '),count:x.instance_count});else if(/Expedition Crate/.test(n)){const label=n.replace(/\s*\d+\s*Variant_(\w+)/,' ($1)').replace(/\s+\d+$/,'');const hit=other.find(o=>o.name===label);if(hit)hit.count+=x.instance_count;else other.push({name:label,count:x.instance_count})}}
 const people=[villagers.adults?`${villagers.adults} adult${villagers.adults===1?'':'s'}`:'',villagers.kids?`${villagers.kids} kid${villagers.kids===1?'':'s'}`:'',villagers.elders?`${villagers.elders} elder${villagers.elders===1?'':'s'}`:'',villagers.babies?`${villagers.babies} bab${villagers.babies===1?'y':'ies'}`:''].filter(Boolean).join(', ');
 const list=(xs,type)=>xs.map(x=>`${type?`<a href="${url(type,x.id)}">${esc(x.name)}</a>`:esc(x.name)}${x.count>1?` ×${x.count}`:''}`).join(', ');
 const rows=[['Villagers',people||'None'],['Already built',built.length?list(built,'buildings'):null],['Stockpile',stock.length?list(stock,'resources'):null],['Tools',tools.length?list(tools):null],['Crates',other.length?list(other):null]].filter(r=>r[1]);
 return `<section class="rule-section"><h2>Starting conditions</h2><dl class="definition start-grid">${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${v}</dd></div>`).join('')}</dl><p class="objective-note">Counted from the map file. Stockpile numbers are items placed on the map and can differ slightly from what the stockpile shows.</p></section>`}
const NEED_UNITS={'Food Need':['FoodUnits','Food','IsConcernFoodAvailable'],'Entertainment Need':['EntertainmentUnits','Fun','IsConcernEntertainmentAvailable'],'Wellness Need':['WellnessUnits','Wellness','IsConcernWellnessAvailable'],'Community Need':['CommunityUnits','Community','IsConcernCommunityAvailable'],'Refreshment Need':['RefreshmentUnits','Cooling','IsConcernRefreshmentAvailable'],'Hydration Need':['HydrationUnits','Hydration','IsConcernHydrationAvailable'],'Heat Need':['HeatUnits','Heat','IsConcernHeatAvailable'],'Energy Need':[null,'Energy (sleep)',null]};
function adultsOnly(r){const a=r.consumption_age_limits;return !!(a&&a.ConsumedByAdults&&!a.ConsumedByChildren)}
function needSatisfiers(unitKey){return uniq(D.resources.filter(r=>r.publicly_named&&r.need_units[unitKey]>0)).sort((a,b)=>b.need_units[unitKey]-a.need_units[unitKey]||a.name.localeCompare(b.name))}
function needsPage(){const hazard={Heat:'Winter',Cooling:'Tropical',Hydration:'Desert'};return `${header('Needs','What satisfies each villager need, from two sources: the units stored on resources, and what the game’s own building descriptions say. The stored units miss dishes with a second effect, carried gear and places, so neither source alone is complete. How fast needs fall and how much each effect is worth are not yet established.','MECHANICS')}${D.needs.map(n=>{const [unitKey,label,concern]=NEED_UNITS[n.name]||[null,n.name,null];const items=unitKey?needSatisfiers(unitKey):[];const levels=concern?W.levels.filter(l=>l.scenario?.level_config?.[0]?.[concern]===true).length:null;const biome=hazard[label]?W.biomes.find(b=>b.id===hazard[label]):null;const text=biome?biomeRule(biome)?.special_needs_and_hazards?.[0]?.text:null;
 return `<section class="rule-section" id="need-${slug(label)}"><h2>${esc(label)}</h2>${text?`<div class="prose"><p>${rich(text)}</p></div>`:''}${items.length?`<div class="article-list">${items.map(r=>`<a href="${url('resources',r.id)}">${icon('resources',r)}<span>${esc(r.name)}${adultsOnly(r)?' <span class="tag amber">adults only</span>':''}</span><small>${fmt(r.need_units[unitKey])} unit${r.need_units[unitKey]===1?'':'s'}</small></a>`).join('')}</div>`:unitKey?'<p>No stored resource carries units for this need.</p>':'<p>Restored by sleeping. No resource carries units for it.</p>'}${unitKey?statedSection(label):''}${levels!==null?`<p class="objective-note">Switched on in ${levels} of ${W.levels.length} levels; older maps may not record the setting.</p>`:''}</section>`}).join('')}<section class="rule-section"><h2>Housing</h2><p>Housing is a need switch on levels but has no resource; it is met by houses. See the ${`<a href="${url('buildings')}">Buildings</a>`} catalog, Housing tab, for capacities.</p></section>`}
const SOURCE_CATEGORY={300149:'rock sources',300150:'wood trees',300152:'planted fields',300154:'cows (milk)',300155:'fruit trees and bushes',300156:'reed plants'};
function harvestRow(b){const cats=[...new Set(b.formula_ids.flatMap(i=>F[i]?.resource_source_category_ids||[]))];if(!cats.length||b.is_plant)return null;return cats.map(c=>esc(SOURCE_CATEGORY[c]||`source category ${c}`)).join(', ')+' <span class="objective-note">(on the map)</span>'}
function placementRow(b){const p=b.placement_rules;if(!p||b.is_plant)return null;const t=p.ValidTerrains||[];const names=t.map(terrainName).map(x=>x.toLowerCase());const terrain=t.length===0?'no soil terrain listed (built at the water’s edge; other constraints apply)':t.length===1&&t[0]===3?'soil':names.join(', ').replace(/, ([^,]*)$/,' or $1');const h=p.MaxAllowedHeightDifference;const slope=h>=1000?'any slope':h>0.2?`slopes up to ${fmt(h)}`:'flat ground';const extra=[p.ConnectsZones?'connects zones':'',p.BuildOverWithBuildSite?'can be laid over build sites':''].filter(Boolean).join(', ');return `${terrain==='soil'&&slope==='flat ground'?'flat soil only':terrain+', '+slope}${extra?', '+extra:''}`}

// Tournament Mode: built from the game's own FastMode text (FastMode.Name resolves to “Tournament”). Seasons are withheld from the public page when the spoiler policy lists them.
function tournamentText(key){return (fullWorld||W).challenges.source_entries.find(e=>e.key===key)?.english||''}
function tText(s){let t=String(s||'');t=t.replace(/\[select value="\{[^}]+\}"\s+1="[^"]*"\s+2="([^"]*)"\]/g,'$1').replace(/\{count\}/g,'N').replace(/\{days\}/g,'N').replace(/\{points\}/g,'N').replace(/<sprite name=[^>]*>/g,'').replace(/\[\{seasonstyle\}\]|\[\{seasonStyle\}\]/gi,'the season’s').replace(/\[FastMode\.Props\.Banner\.Name\]/g,tournamentText('FastMode.Props.Banner.Name')||'Tournament Banner').replace(/\[Concern\.([A-Za-z]+)\.Name\]/g,(_,k)=>k==='Nutrition'?'Food':k==='Entertainment'?'Fun':k==='Refreshment'?'Cooling':k).replace(/\{Concern\.([A-Za-z]+)\.WithIcon\}/g,(_,k)=>k==='Nutrition'?'Food':k==='Entertainment'?'Fun':k==='Refreshment'?'Cooling':k).replace(/\{UI\.Boost\.([A-Za-z]+)\.WithIcon\}/g,'$1 Boost').replace(/\s+/g,' ').trim();return rich(t)}
function tournamentSeasons(){const entries=(fullWorld||W).challenges.source_entries;const ids=[...new Set(entries.filter(e=>/^FastMode\.[A-Za-z]+\.Name\.WithArticle$/.test(e.key)).map(e=>e.key.split('.')[1]))];return ids.map(id=>{const name=tournamentText(`FastMode.${id}.Name`)||id;const rewards=entries.filter(e=>e.key.startsWith(`FastMode.${id}.Reward.`)&&/\.Title$/.test(e.key)).map(e=>({n:+e.key.split('.')[3],title:e.english,description:tournamentText(e.key.replace(/Title$/,'Description'))})).sort((a,b)=>a.n-b.n);return {id,name,rewards,entries:entries.filter(e=>e.key.startsWith(`FastMode.${id}.`)).length,spoiler:spoilerEntry('tournament',id)}})}
function tournamentPage(showAll=false){return tournamentPageInner(showAll).replace(/<details open class="source"/g,'<details class="source"')}
function tournamentPageInner(showAll=false){const obs=(fullWorld||W).contributions?.filter(x=>x.target.type==='tournament')||[];const live=obs.find(x=>/live|current|running/i.test(x.claim)&&x.status==='confirmed');const seasons=tournamentSeasons().map(s=>({...s,current:!!(live&&live.target.id===s.id)})).sort((a,b)=>(b.current?1:0)-(a.current?1:0)),visible=seasons.filter(s=>showAll||!s.spoiler),withheld=seasons.filter(s=>s.spoiler);const T=tournamentText;const entries=(fullWorld||W).challenges.source_entries;
 const actions=entries.filter(e=>/^FastMode\.Action\.[A-Za-z.]+\.Name$/.test(e.key)).map(e=>({name:e.english,description:T(e.key.replace(/\.Name$/,'.Description'))}));
 const tutorials=W.levels.filter(l=>l.category==='tournament_tutorial').sort((a,b)=>a.id.localeCompare(b.id));
 const quote=keys=>`<ul class="check-list">${keys.map(k=>`<li>${tText(T(k))}</li>`).join('')}</ul>`;
 return `${showAll?`<aside class="notice"><div><strong>Spoilers: all Tournament seasons</strong><p>This view includes season styles withheld from the regular page because their release is unconfirmed.</p><a href="${url('spoilers')}">Spoiler index</a> · <a href="${url('tournament')}">Regular Tournament page</a></div></aside>`:''}${header('Tournament Mode','A daily, turn-based mode with its own levels, tiles, streaks, reward points and seasonal cosmetic styles, described in the game’s own words. The game files call it “FastMode”.','PLAY MODES')}<div class="tags">${tag('Recovered game text')}${live?tag(`Live · ${live.evidence.kind.replace('-',' ')} ${live.evidence.date}`):tag('Availability not checked on this installation','gray')}</div>
 <section class="rule-section"><h2>What it is</h2><div class="prose"><p>${tText(T('FastMode.LevelMenu.Description'))}</p><p>${tText(T('FastMode.Popup.TournamentIntro.Description'))}</p><p>${tText(T('FastMode.LevelInGame.Description'))}</p></div></section>
 <section class="rule-section"><h2>How a level plays</h2><p>From the Tournament Tutorial, in the game’s words:</p>${quote(['FastMode.Tutorial.Level1.Shared.Actions.1','FastMode.Tutorial.Level1.Shared.Bag.4','FastMode.Tutorial.Level1.Shared.Bag.5','FastMode.Tutorial.Level1.Shared.Skip.1','FastMode.Tutorial.Level1.Shared.Skip.2','FastMode.Tutorial.Level1.Shared.Skip.3'])}${tutorials.length?`<p>Tutorial levels: ${tutorials.map(l=>`<a href="${url('levels',l.id)}">${esc(l.name)}</a>`).join(', ')}.</p>`:''}</section>
 <section class="rule-section"><h2>Tiles</h2><p>The tiles a level can draw. Durations and counts are set per tile; the text shows the plural form.</p><div class="table-wrap"><table><thead><tr><th scope="col">Tile</th><th scope="col">Effect</th></tr></thead><tbody>${actions.map(a=>`<tr><td>${tText(a.name)}</td><td>${tText(a.description)}</td></tr>`).join('')}</tbody></table></div></section>
 <section class="rule-section"><h2>Reward Points, streaks and leaderboards</h2>${quote(['FastMode.RewardPoint.Description','FastMode.Level.MainObjectives.Description','FastMode.Level.OptionalObjectives.Description','FastMode.Streak.Inactive.Description','FastMode.Popup.Reward.StreakShield.Description','FastMode.UI.Leaderboards.TodayDescription','FastMode.UI.Leaderboards.OtherDayDescription'])}</section>
 <section class="rule-section"><h2>Seasons and styles</h2><p>${tText(T('FastMode.NewSeason.WelcomeDescription'))}</p>${visible.map(s=>`<h3>${esc(s.name)}${s.current?' '+tag(`Current season · reported ${esc(live.evidence.date)}`):''}${s.spoiler?' '+tag('Release unconfirmed','amber'):''}</h3>${s.current&&!s.rewards.length?`<p class="small">The live season’s reward set is not in the extracted text; completed seasons keep theirs in the files.</p>`:''}${s.rewards.length?`<ol class="story-levels">${s.rewards.map(r=>`<li>${tText(r.title)}${r.description?` <span class="objective-note">${tText(r.description)}</span>`:''}</li>`).join('')}</ol>`:s.current?'':`<p class="small">Only the style name is stored; no reward set.</p>`}`).join('')}${!showAll&&withheld.length?`<p class="small">${withheld.length} further season style${withheld.length>1?'s are':' is'} listed in the <a href="${url('spoilers')}">Spoilers</a> section because no release evidence exists for ${withheld.length>1?'them':'it'}.</p>`:''}</section>
 ${live?`<section class="rule-section"><h2>Observations</h2>${obs.map(x=>`<p><strong>${esc(x.claim)}</strong> <span class="objective-note">${esc(x.status)} · ${esc(x.evidence.kind.replace('-',' '))} · ${esc(x.evidence.date)}</span><br>${esc(x.notes||'')}</p>`).join('')}<p class="small">Seasons rotate; the wiki does not yet track their dates.</p></section>`:notice('Availability on this installation not checked','The menu observations of 24 October covered campaigns and the challenge archive, not Tournament Mode. Whether the mode, a current season, or either reward set is live has not been confirmed.')}${source({text_tables:['FastMode','FastSeasons','FastModeTutorial'],seasons:visible.map(s=>({id:s.id,name:s.name,text_entries:s.entries,reward_titles:s.rewards.length,release_unconfirmed:!!s.spoiler})),withheld_seasons:showAll?0:withheld.length},'Tournament text sources')}`}

// Need effects stated in the game's own building descriptions. Stored resource units miss dishes with a second effect, carried gear and places, so the descriptions are a second evidence source.
const CONCERN_LABEL={Nutrition:'Food',Food:'Food',Community:'Community',Entertainment:'Fun',Wellness:'Wellness',Heat:'Heat',Refreshment:'Cooling',Hydration:'Hydration'};
const CONCERN_UNIT={Food:'FoodUnits',Community:'CommunityUnits',Fun:'EntertainmentUnits',Wellness:'WellnessUnits',Heat:'HeatUnits',Cooling:'RefreshmentUnits',Hydration:'HydrationUnits'};
function statedEffects(){const out=[];for(const b of uniq(D.buildings.filter(b=>!isSuppressed('buildings',b.gameobject_id)&&b.description))){const concerns=[...new Set([...b.description.matchAll(/\{Concern\.([A-Za-z]+)\./g)].map(m=>CONCERN_LABEL[m[1]]).filter(Boolean))];if(!concerns.length)continue;
 const outputs=[...new Set(b.formula_ids.flatMap(i=>F[i]?.outputs.map(o=>o.resource_id)||[]))].map(id=>R[id]).filter(r=>r&&r.publicly_named);const gear=/carry around|equippable|wearer/i.test(b.description);
 for(const need of concerns){const unit=CONCERN_UNIT[need];const carriers=outputs.filter(r=>r.need_units[unit]>0);const item=outputs.find(r=>!gear?r.need_units.FoodUnits>0||r.need_units[unit]>0:true)||outputs[0]||null;
  out.push({need,building:b,item,kind:!outputs.length?'place':gear?'gear':'dish',stored:carriers.length>0})}}return out}
function statedFor(need){return statedEffects().filter(e=>e.need===need)}
function statedSection(need){const rows=statedFor(need).filter(e=>!e.stored);if(!rows.length)return '';const group=kind=>rows.filter(e=>e.kind===kind);const amount=e=>{if(e.kind==='gear'&&e.item){const g=gearFor(e.item);if(g&&g.config?.BaseValueIncrease)return ` <span class="objective-note">base +${fmt(g.config.BaseValueIncrease)} (stored)</span>`}const v=socialNeedValue(e.building,e.need);return v!==null?` <span class="objective-note">${fmt(v)} (stored)</span>`:''};const link=e=>e.item?`<a href="${url('resources',e.item.id)}">${esc(e.item.name)}</a> <span class="objective-note">from the <a href="${url('buildings',e.building.gameobject_id)}">${esc(e.building.name)}</a></span>${amount(e)}`:`<a href="${url('buildings',e.building.gameobject_id)}">${esc(e.building.name)}</a>${amount(e)}`;
 const part=(title,xs)=>xs.length?`<p><strong>${title}:</strong> ${xs.map(link).join('; ')}</p>`:'';return `<div class="stated"><p class="objective-note">Also, according to the game’s building descriptions. Where a value is shown it is stored on the building’s social or eating spot, or on the gear item; how those values convert to the need meter is unverified. Dishes get their second effect when eaten at their building:</p>${part('Dishes',group('dish'))}${part('Carried gear',group('gear'))}${part('Places',group('place'))}</div>`}
function resourceStatedEffects(r){const vals=Object.fromEntries(Object.entries(r.need_units).filter(([,v])=>v));return statedEffects().filter(e=>e.item&&e.item.id===r.id&&!(vals[CONCERN_UNIT[e.need]]>0))}

// Research findings (content/reference/research-findings.json): decoded gear, social-spot, terrain and production-profile data handed over by the research agent. Rates are a supplied-inputs capacity model, never measured output.
function profileFor(b){const p=RF.profiles?.[b.gameobject_id];if(p)return p;const byName=Object.values(RF.profiles||{}).find(x=>x.name===b.name);return byName||null}
function gearFor(r){return (RF.gear_findings?.records||[]).find(g=>g.name===r.name)||null}
function socialFor(b){return (RF.social_spot_findings?.records||[]).filter(s=>{const target=B[s.building_id];return target&&target.name===b.name})}
function socialUnits(rec){const map={CommunityUnits:'Community',EntertainmentUnits:'Fun',WellnessUnits:'Wellness',HeatUnits:'Heat',RefreshmentUnits:'Cooling',HydrationUnits:'Hydration'};return Object.entries(rec.config||{}).filter(([k,v])=>map[k]&&v>0).map(([k,v])=>({need:map[k],units:+v.toFixed(2)}))}
function socialRow(b){const recs=socialFor(b);if(!recs.length)return null;const parts=recs.flatMap(rec=>socialUnits(rec).map(u=>`${esc(u.need)} ${fmt(u.units)}${rec.class==='WorkspotCompleteModifyNeed'?' when a worker finishes tending it':''}`));return parts.length?`${[...new Set(parts)].join(', ')} <span class="objective-note">(stored on its ${recs.some(r=>r.class==='SocialSpotBehaviour')?'social spot':'workspot'}; how it converts to the need meter is unverified)</span>`:null}
function socialNeedValue(b,need){for(const rec of socialFor(b))for(const u of socialUnits(rec))if(u.need===need)return u.units;return null}
function terrainName(code){return RF.terrain_placement_findings?.values?.[String(code)]||`terrain ${code}`}
function gearRow(r){const g=gearFor(r);if(!g)return null;const c=g.config||{};const parts=[];if(g.need&&g.need!=='None')parts.push(`raises base ${esc(g.need==='Entertainment'?'Fun':g.need==='Refreshment'?'Cooling':g.need)} <span class="objective-note">(stored value ${fmt(c.BaseValueIncrease)}; how it applies is unverified)</span>`);if(c.WalkSpeedMultipliers?.Base)parts.push(`walk speed ×${fmt(+c.WalkSpeedMultipliers.Base.toFixed(2))}${c.WalkSpeedMultipliers.Road?`, ×${fmt(+c.WalkSpeedMultipliers.Road.toFixed(2))} on roads`:''}`);if(c.AdultsOnly)parts.push('adults only');return parts.length?parts.join(' · '):'no stored effect'}
function yieldRow(b){const p=profileFor(b);if(!p||!p.yield?.length)return null;return p.yield.map(y=>`${fmt(y.count)} <a href="${url('resources',y.resource_id)}">${esc(R[y.resource_id]?.name||y.name)}</a> per full field`).join(', ')+(p.planting_positions?` <span class="objective-note">(${p.planting_positions} planting spot${p.planting_positions===1?'':'s'})</span>`:'')}
function reportedRateRow(b){const p=profileFor(b);const r=p?.reported_rate;if(!r)return null;return `up to ${fmt(r.count)} <a href="${url('resources',r.resource_id)}">${esc(R[r.resource_id]?.name||'')}</a> per ${r.days===1?'day':r.days+' days'} <span class="objective-note">(player report)</span>`}
function productionHighlights(b){const p=profileFor(b);if(!p?.highlights?.length)return '';return `<section class="rule-section"><h2>Production notes</h2><p class="objective-note">From decoded stage timings and a supplied-inputs model; ceilings, not measured output.</p><ul class="check-list">${p.highlights.map(h=>`<li>${esc(h)}</li>`).join('')}</ul></section>`}
function productionModelResearch(b){const p=profileFor(b);if(!p)return '';const rates=(p.products||[]).filter(x=>x.rates?.length);const blockers=(p.products||[]).flatMap(x=>x.blockers||[]);if(!rates.length&&!blockers.length&&!p.notes?.length)return '';
 return `<section class="rule-section"><h2>Modelled production capacity</h2><p>A game day is ${fmt(RF.seconds_per_day)} simulation seconds${p.workday_fraction?` and this building works ${fmt(Math.round(p.workday_fraction*100))}% of it`:''}. The model assumes all inputs delivered and output cleared, and excludes walking, handoffs and contention; it is a ceiling for comparison, not a measured yield.</p>${rates.map(pr=>`<div class="table-wrap"><table><thead><tr><th>Workers</th><th>Batches per day</th><th>Output per day</th><th>Limited by</th></tr></thead><tbody>${pr.rates.map(rt=>`<tr><td>${rt.workers}</td><td>${fmt(+rt.batches_per_day.toFixed(2))}</td><td>${rt.outputs_per_day.map(o=>`${fmt(+o.per_day.toFixed(1))} ${esc(o.name)}`).join(', ')}</td><td>${esc(rt.limiting_stage||'')}</td></tr>`).join('')}</tbody></table></div>`).join('')}${blockers.length?`<p class="small">No daily estimate: ${esc([...new Set(blockers)].join('; '))}.</p>`:''}${p.notes?.length?`<ul class="check-list">${p.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:''}${source({profile:p,provenance:RF.provenance},'Production profile')}</section>`}
